WITH kept AS (SELECT s.* FROM accounts s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time < '2025-09-01')) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, SUM(balance) AS total_balance, COUNT(DISTINCT account_type) AS distinct_account_types, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS balance_per_closed, SUM(balance) FILTER (WHERE status = 'FROZEN') AS frozen_total_balance, PERCENTILE_APPROX(balance, 0.9) AS balance_p90 FROM kept GROUP BY ROLLUP (DATE_TRUNC('WEEK', opened_date))
